// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures it is ready before frame 0
const { fontFamily: interFamily } = loadInter();



export type ModernGlassRevealProps = Record<string, any>;

const ModernGlassReveal: React.FC<ModernGlassRevealProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Step 1",
  bodyText = "If you have completed a Master’s degree, especially from a Public University, then in 2026 you do not have a PAL requirement.",
  gradientStart = "#1e1b4b", // Deep indigo
  gradientEnd = "#000000",
  boxColor = "rgba(255, 255, 255, 0.03)",
  textColor = "#ffffff",
  outlineColor = "rgba(167, 139, 250, 0.6)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Global Timing for Outro
  const outroStart = durationInSeconds * fps - 30;
  const globalOpacity = interpolate(
    frame,
    [outroStart, outroStart + 15],
    [1, 0],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );
  const globalBlur = interpolate(frame, [outroStart, outroStart + 15], [0, 20], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Background Animation
  const bgRotation = interpolate(frame, [0, fps * durationInSeconds], [130, 160]);
  const backgroundStyle = transparentBackground
    ? { backgroundColor: bgColor }
    : { background: `linear-gradient(${bgRotation}deg, ${gradientStart}, ${gradientEnd})` };

  // Box Calculations (Responsive to Canvas)
  const boxW = width * 0.85;
  const boxH = height * 0.45;
  const borderRadius = 40;
  
  // Perimeter estimation for SVG drawing animation
  const perimeter = (boxW + boxH) * 2;

  // Box Entry Animation
  const boxScale = spring({
    fps,
    frame: frame - 10,
    config: { damping: 14, mass: 0.8, stiffness: 100 },
  });
  
  const boxOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Outline Entry Animation
  const outlineProgress = spring({
    fps,
    frame: frame - 25,
    config: { damping: 100, mass: 2, stiffness: 40 },
  });
  const strokeOffset = interpolate(outlineProgress, [0, 1], [perimeter, 0]);

  // Title Entry Animation
  const titleY = interpolate(
    spring({ fps, frame: frame - 35, config: { damping: 12 } }),
    [0, 1],
    [20, 0]
  );
  const titleOpacity = interpolate(frame, [35, 50], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Split text for staggered reveal
  const words = bodyText.split(" ");

  return (
    <AbsoluteFill
      style={{
        ...backgroundStyle,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
        opacity: globalOpacity,
        filter: `blur(${globalBlur}px)`,
        color: textColor,
      }}
    >
      <div
        style={{
          width: boxW,
          height: boxH,
          backgroundColor: boxColor,
          borderRadius: `${borderRadius}px`,
          position: "relative",
          display: "flex",
          flexDirection: "column",
          padding: `${height * 0.06}px ${width * 0.08}px`,
          transform: `scale(${boxScale})`,
          opacity: boxOpacity,
          backdropFilter: "blur(24px)",
          WebkitBackdropFilter: "blur(24px)",
          boxShadow: `0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 60px ${outlineColor.replace(
            /[^,]+(?=\))/,
            "0.15"
          )}`,
        }}
      >
        {/* Animated SVG Outline */}
        <svg
          width={boxW}
          height={boxH}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            pointerEvents: "none",
            borderRadius: `${borderRadius}px`,
          }}
        >
          <rect
            x={1.5}
            y={1.5}
            width={boxW - 3}
            height={boxH - 3}
            rx={borderRadius - 1.5}
            fill="none"
            stroke={outlineColor}
            strokeWidth={3}
            strokeDasharray={perimeter}
            strokeDashoffset={strokeOffset}
            strokeLinecap="round"
          />
        </svg>

        {/* Content Wrapper */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", zIndex: 10 }}>
          {/* Title */}
          <h2
            style={{
              fontSize: width * 0.06,
              fontWeight: 700,
              margin: 0,
              marginBottom: height * 0.03,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              letterSpacing: "-0.02em",
              textTransform: "uppercase",
              color: outlineColor.replace(/[^,]+(?=\))/, "1"), // Solid version of outline color
            }}
          >
            {title}
          </h2>

          {/* Body Text */}
          <div
            style={{
              fontSize: width * 0.045,
              fontWeight: 400,
              lineHeight: 1.5,
              display: "flex",
              flexWrap: "wrap",
              alignContent: "flex-start",
            }}
          >
            {words.map((word, i) => {
              // Stagger each word's animation
              const wordFrame = frame - 45 - i * 2;
              const wordOpacity = interpolate(wordFrame, [0, 10], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
              const wordY = interpolate(wordFrame, [0, 10], [15, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    opacity: wordOpacity,
                    transform: `translateY(${wordY}px)`,
                    marginRight: "0.25em",
                    marginBottom: "0.2em",
                    textShadow: "0 2px 10px rgba(0,0,0,0.2)",
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ModernGlassReveal;